// Pega aquí tu enlace de reseñas de Google (Perfil de Empresa → "Pedir reseñas"). Sin él no se envía nada.
const REVIEW_URL = 'https://g.page/r/CYnyzOuZY0jbEBM/review';
if (!/^https:\/\//.test(REVIEW_URL)) throw new Error('Falta el enlace de reseñas en el nodo Configuración.');
return [{ json: { review: REVIEW_URL } }];

const b = $json;
const host = String(b.audited_url).replace(/^https?:\/\//, '').replace(/\/$/, '');
const nombre = String(b.name || '').trim().split(/\s+/)[0] || 'hola';
return { json: { Email: b.email, Nombre: nombre, Host: host, Resena: $('Configuración').first().json.review } };
